        var combinedFeatCount=(s7dData.combined&&s7dData.combined.features)?s7dData.combined.features.length:0;
        var ndviFeatCount=(s7dData.ndvi&&s7dData.ndvi.features)?s7dData.ndvi.features.length:0;
