        lines.push('BEFORE: '+beforeStartTxt+' + '+beforeMonths+'mo | AFTER: '+afterStartTxt+' + '+afterMonths+'mo | radius='+radiusKm+'km');
        if(_pre && _pre.note) lines.push(_pre.note);   // v10.161 S4
        s7fResultV.setValue(lines.join('\n'));
